    <style>
        .ms-hww,
        .ms-hww * {
            box-sizing: border-box;
        }

        .ms-hww {
            --purple: #5A2EA6;
            width: 100%;
            padding: 60px 20px 70px;
            background: #fff;
            font-family: 'Poppins', Arial, sans-serif;
        }

        .ms-hww-wrap {
            max-width: 1110px;
            margin: 0 auto;
        }

        .ms-hww-title {
            margin: 0 0 20px;
            text-align: center;
            font-size: 44px;
            line-height: 1.2;
            font-weight: 600;
            color: #000;
        }

        .ms-hww-title span {
            color: var(--purple);
        }

        .ms-hww-intro {
            margin: 0 auto 60px;
            max-width: 1040px;
            text-align: center;
            font-size: 14px;
            line-height: 1.75;
            font-weight: 400;
            color: #222;
        }

        .ms-hww-grid {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 24px;
        }

        .ms-hww-card {
            padding: 34px 30px 36px;
            border-radius: 24px;
            border: 1px solid #ececec;
            background: #f6f6f6;
            text-align: center;
            transition: .3s ease;
        }

        .ms-hww-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 12px 28px rgba(90, 46, 166, .16);
        }

        .ms-hww-icon {
            width: 62px;
            height: 62px;
            margin: 0 auto 18px;
            border-radius: 50%;
            border: 1px solid #111;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .ms-hww-icon svg {
            width: 28px;
            height: 28px;
            fill: #111;
        }

        .ms-hww-card h3 {
            margin: 0 0 14px;
            font-size: 20px;
            line-height: 1.35;
            font-weight: 600;
            color: #000;
        }

        .ms-hww-card p {
            margin: 0;
            font-size: 14px;
            line-height: 1.8;
            font-weight: 400;
            color: #222;
        }

        /* ---------- Responsive ---------- */
        @media (max-width: 991px) {
            .ms-hww-grid {
                grid-template-columns: repeat(2, minmax(0, 1fr));
                gap: 20px;
            }

            .ms-hww-title {
                font-size: 36px;
            }
        }

        @media (max-width: 575px) {
            .ms-hww {
                padding: 35px 14px 45px;
            }

            .ms-hww-title {
                font-size: 30px;
            }

            .ms-hww-intro {
                font-size: 14px;
                margin-bottom: 32px;
            }

